  fetchFilteredComparison() {
    const bidcodeSearch = this.bidcodeSearch;
    if (!this.financialYear) {
      alert("Please select a Financial Year");
      return;
    }
    this.isLoading = true;
    const payload = {
      bidCode: bidcodeSearch,
      financialYear: this.financialYear || "",
      department: this.department || "",
      selectedOfficeAddress: this.selectedOfficeAddress || "",
      bidClosingFromDate: this.formatDate(this.bidClosingFromDate),
      bidClosingToDate: this.formatDate(this.bidClosingToDate),
      chartType: this.chartType || "1"
    };
    console.log("Search payload:", payload);
    this.generalService.httpPost(COMPARISONCHARTSURL.COMPARISONCHARTSDATA, payload).subscribe((response) => {
      if (response && response.msgStatus === "S") {
        this.originalTenders = (response.result || []).map((tender) => __spreadProps(__spreadValues({}, tender), {
          docSize: this.extractDocSize(tender.docPdfString)
        }));
        this.currentPage = 1;
        this.applyFilters();
        this.isLoading = false;
      } else {
        this.originalTenders = [];
        this.allTenders = [];
        this.totalPages = 0;
        this.isLoading = false;
      }
    }, (error) => {
      console.error("Error fetching tenders:", error);
      this.originalTenders = [];
      this.allTenders = [];
      this.totalPages = 0;
      this.isLoading = false;
    });
  }
  downloadTender(tender) {
    let tenderData;
    try {
      tenderData = JSON.parse(this.decodeInvalidLang(tender?.docPdfString || ""));
    } catch {
      alert("No document available for this tender.");
      return;
    }
    if (!tenderData.id) {
      alert("No document available for this tender.");
      return;
    }
    const payload = {
      documentId: tenderData.id,
      tableName: tenderData.table
    };
    this.generalService.httpPost(DOCUMENTSURL.DOCUMENTSDATA, payload).subscribe((response) => {
      if (response && response.msgStatus === "S") {
        const byteArray = response.result?.docPdf;
        if (byteArray && byteArray.length > 0) {
          const uint8Array = new Uint8Array(byteArray);
          const blob = new Blob([uint8Array], { type: "application/pdf" });
          const blobUrl = URL.createObjectURL(blob);
          const a = document.createElement("a");
          a.href = blobUrl;
          a.download = tender.bidTitle ? tender.bidTitle + ".pdf" : "document.pdf";
          document.body.appendChild(a);
          a.click();
          a.remove();
          URL.revokeObjectURL(blobUrl);
        } else {
          alert("No PDF data found for this document.");
        }
      } else {
        alert("Failed to fetch document: " + (response?.message || "Unknown error"));
      }
    }, (error) => {
      console.error("Error fetching document:", error);
      alert("Error fetching document.");
    });
  }
