  convertToUSFormat(dateStr) {
    if (!dateStr)
      return dateStr;
    const cleaned = dateStr.trim();
    const match3 = cleaned.match(/^(\d{2})-(\d{2})-(\d{4})(?:\s+(\d{2}:\d{2}:\d{2}))?$/);
    if (!match3)
      return dateStr;
    const [, dd, mm, yyyy, time] = match3;
    return `${mm}/${dd}/${yyyy}${time ? " " + time : ""}`;
  }
