  parseAndDecodeJson(raw) {
    try {
      const cleanedJson = raw.replace(/\\([0-7]{3})/g, (_, octal) => String.fromCharCode(parseInt(octal, 8)));
      return JSON.parse(cleanedJson);
    } catch (error) {
      console.error("\u274C Failed to parse JSON:", error, raw);
      return null;
    }
  }
  rearrangeBidCode(code) {
    const match3 = code.match(/^([A-Z]+)(\d{4})([A-Z]\d+)$/);
    if (match3) {
      const [, prefix, year, suffix] = match3;
      return `${year}${prefix}${suffix}`;
    }
    return code;
  }
  fetchgettenderid(nibKey) {
    const payload = {
      nibKey: this.rearrangeBidCode(nibKey)
    };
    this.generalService.httpPost(GETTENDERIDSURL.GETTENDERIDSDATA, payload).subscribe((response) => {
      if (response && response.msgStatus === "S" && response.result?.tenderId) {
        this.tenderId = response.result.tenderId;
        console.log("Tender ID retrieved:", this.tenderId);
      } else {
        this.tenderId = "";
        console.warn("No tenderId returned in response.");
      }
    }, (error) => {
      this.tenderId = "";
      console.error("Error fetching tender ID:", error);
    });
  }
  resolveBidPdfType(bidDocPdfString) {
    let isBidDirectUrl = false;
    let isPdfAvailable = false;
    let bidDocParsed = null;
    if (bidDocPdfString && bidDocPdfString.trim()) {
      try {
        bidDocParsed = JSON.parse(bidDocPdfString);
        if (bidDocParsed?.id && bidDocParsed?.table) {
          isBidDirectUrl = false;
          isPdfAvailable = true;
        } else {
          isBidDirectUrl = true;
          isPdfAvailable = true;
        }
      } catch (e) {
        console.warn("\u26A0\uFE0F Normal JSON.parse failed, trying to clean octal escapes...");
        bidDocParsed = this.parseAndDecodeJson(bidDocPdfString);
        if (bidDocParsed && typeof bidDocParsed === "object") {
          if (bidDocParsed?.id && bidDocParsed?.table) {
            isBidDirectUrl = false;
            isPdfAvailable = true;
          } else {
            isBidDirectUrl = true;
            isPdfAvailable = true;
          }
        } else {
          isBidDirectUrl = true;
          bidDocParsed = bidDocPdfString;
          isPdfAvailable = true;
        }
      }
    } else {
      isPdfAvailable = false;
    }
    return { isBidDirectUrl, isPdfAvailable, bidDocParsed };
  }
