  getSizeInKB(sizeInBytes) {
    const bytes = Number(sizeInBytes);
    if (!bytes || isNaN(bytes) || bytes <= 0)
      return "0 KB";
    const sizeInKB = bytes / 1024;
    if (sizeInKB > 1024) {
      const sizeInMB = sizeInKB / 1024;
      return `${sizeInMB.toFixed(2)} MB`;
    }
    return `${sizeInKB.toFixed(2)} KB`;
  }
