  applyFilters() {
    let filtered = [...this.allTenders];
    const search = this.searchText.trim().toLowerCase();
    if (search) {
      filtered = filtered.filter((tender) => tender.bidTitle?.toLowerCase().includes(search) || tender.bidKey?.toLowerCase().includes(search) || tender.win?.toLowerCase().includes(search) || tender.nibCode?.toLowerCase().includes(search));
    }
    this.totalPages = this.selectedCount === -1 ? 1 : Math.ceil(filtered.length / this.itemsPerPage);
    if (this.selectedCount === -1) {
      this.filteredTenders = filtered;
    } else {
      const startIndex = (this.currentPage - 1) * this.itemsPerPage;
      const endIndex = startIndex + this.itemsPerPage;
      this.filteredTenders = filtered.slice(startIndex, endIndex);
    }
  }
  onTypeChange(event) {
    this.selectedType = event;
    this.applyFilters();
  }
