  fetchFilteredNibs() {
    const rfpCodeToSearch = this.nibCode?.trim() || "";
    const referenceNoToSearch = this.nibReferenceNo?.trim() || "";
    const isBasicFieldsEmpty = !rfpCodeToSearch && !referenceNoToSearch;
    if (isBasicFieldsEmpty) {
      if (!this.financialYear) {
        alert("Please select a Financial Year.");
        return;
      }
    }
    const captchaIsValid = this.captchaComponent.validateCaptcha();
    if (!captchaIsValid) {
      return;
    }
    this.isLoading = true;
    const payload = {
      txtrfpcode: rfpCodeToSearch,
      ddlFinancialYear: this.financialYear || "0",
      ddlDepartment: this.department || "0",
      txtrfprefno: referenceNoToSearch,
      txtrfppubfromdate: this.npfromDate || "",
      txtrfppubtodate: this.nptoDate || "",
      ddltypeofchart: "",
      ddlOptiontype: ""
    };
    console.log("Sending New Payload:", payload);
    this.generalService.httpPost(GETRFPSEARCHDETAILURL.RFPSEARCHDETAILDATA, payload).subscribe((response) => {
      if (response && response.msgStatus === "S") {
        this.allTenders = response.result.map((item) => ({
          publishDate: item.rfpPublishDate,
          nibCode: item.rfpKey,
          nibReferenceNo: item.rfpReferenceNo,
          deptName: item.deptName,
          numberOfBids: 0,
          nibKey: item.rfpKey
          // reuse rfpKey for click events
        }));
        this.filteredTenders = [...this.allTenders];
        this.applyFilters();
        this.isLoading = false;
        if (this.allTenders.length === 0) {
          alert("No records found for the given criteria.");
        }
      } else {
        this.allTenders = [];
        this.filteredTenders = [];
        this.isLoading = false;
        alert("No data found or something went wrong.");
      }
    }, (error) => {
      this.allTenders = [];
      this.filteredTenders = [];
      this.isLoading = false;
      alert("Something went wrong while fetching data.");
    });
  }
  sortData(column) {
    if (!this.filteredTenders || this.filteredTenders.length === 0)
      return;
    if (this.sortColumn === column) {
      this.sortDirection = this.sortDirection === "asc" ? "desc" : "asc";
    } else {
      this.sortColumn = column;
      this.sortDirection = "asc";
    }
    this.filteredTenders.sort((a, b) => {
      let valueA = a[column];
      let valueB = b[column];
      if (typeof valueA === "string" && typeof valueB === "string" && !isNaN(Date.parse(valueA)) && !isNaN(Date.parse(valueB))) {
        valueA = new Date(valueA);
        valueB = new Date(valueB);
      }
      if (valueA == null)
        return 1;
      if (valueB == null)
        return -1;
      let comparison = 0;
      if (typeof valueA === "string" && typeof valueB === "string") {
        comparison = valueA.localeCompare(valueB);
      } else if (typeof valueA === "number" && typeof valueB === "number") {
        comparison = valueA - valueB;
      } else if (valueA instanceof Date && valueB instanceof Date) {
        comparison = valueA.getTime() - valueB.getTime();
      }
      return this.sortDirection === "asc" ? comparison : -comparison;
    });
  }
