  fetchFilteredSCMs() {
    if (!this.financialYear || this.financialYear.trim() === "") {
      alert("Please select financial year.");
      return;
    }
    const captchaIsValid = this.captchaComponent.validateCaptcha();
    if (!captchaIsValid) {
      return;
    }
    this.isLoading = true;
    const payload = {
      txtsccode: this.scKey.trim(),
      ddlFinancialYear: this.financialYear,
      ddlDepartment: this.department,
      txtscrefno: this.nibReferenceNo.trim(),
      txtscpubfromdate: this.npfromDate ? this.formatDate(this.npfromDate) : "",
      txtscpubtodate: this.nptoDate ? this.formatDate(this.nptoDate) : ""
    };
    console.log("Sending Payload:", payload);
    this.generalService.httpPost(GETSCMSEARCHURL.GETSCMSEARCHATA, payload).subscribe((response) => {
      if (response && response.msgStatus === "S" && response.result) {
        const res = response.result;
        this.isLoading = false;
        console.log("res", res);
        console.log("Is array?", Array.isArray(res));
        if (Array.isArray(res)) {
          this.filteredTenders = res.map((item) => ({
            deptCode: item.deptCode,
            deptName: item.deptName,
            finYear: item.finYear,
            scLetterNo: item.scLetterNo,
            scPublishDate: item.scPublishDate,
            scmKey: item.scKey
          }));
        } else {
          this.filteredTenders = [
            {
              deptCode: res.deptCode,
              deptName: res.deptName,
              finYear: res.finYear,
              scLetterNo: res.scLetterNo,
              scPublishDate: res.scPublishDate,
              scKey: res.scKey
            }
          ];
        }
        console.log("Filtered Tenders:", this.filteredTenders);
      } else {
        this.filteredTenders = [];
        alert("No data found for the given SC Key.");
      }
    }, (error) => {
      this.filteredTenders = [];
      alert("Something went wrong while fetching SCM data.");
    });
  }
  formatDate(date) {
    const d = new Date(date);
    const day = String(d.getDate()).padStart(2, "0");
    const month = String(d.getMonth() + 1).padStart(2, "0");
    const year = d.getFullYear();
    return `${day}/${month}/${year}`;
  }
  applyFilters() {
    let filtered = [...this.allTenders];
    const search = this.searchText.trim().toLowerCase();
    if (search) {
      filtered = filtered.filter((tender) => {
        return tender.nibCode?.toLowerCase().includes(search) || tender.bidKey?.toLowerCase().includes(search) || tender.deptName?.toLowerCase().includes(search) || tender.nibReferenceNo?.toLowerCase().includes(search) || this.formatDate(tender.publishDate)?.includes(search);
      });
    }
    this.totalPages = Math.ceil(filtered.length / this.itemsPerPage);
    const start = (this.currentPage - 1) * this.itemsPerPage;
    const end = start + this.itemsPerPage;
    this.filteredCount = filtered.length;
    if (this.itemsPerPage === -1) {
      this.filteredTenders = filtered;
    } else {
      this.filteredTenders = filtered.slice(start, end);
    }
  }
