  printAsPDF() {
    const printContents = document.getElementById("pdfContent");
    if (!printContents) {
      console.error("PDF content not found.");
      return;
    }
    const originalContents = document.body.innerHTML;
    const printStyles = `
  <style>
    body {
      font-family: Arial, sans-serif;
      margin: 20px;
            font-size: 12px;

    }

    .card {
      border: 1px solid #ccc;
      padding: 16px;
      margin-bottom: 16px;
      border-radius: 8px;
    }

    table {
      width: 100%;
      border-collapse: collapse;
      min-width: 600px; /* Force desktop layout */
    }

    th, td {
      padding: 8px;
      border: 1px solid #ddd;
      text-align: left;
      vertical-align: top;
    }

    h5 {
      margin-top: 0;
    }

    .section-title {
      font-weight: bold;
      font-size: 12px;
      margin-bottom: 10px;
    }

    .text-right {
      text-align: right;
    }

    /* Remove responsive overflow during print */
    .responsive-table-container {
      overflow: visible !important;
    }

    /* Hide collapsed rows during print */
    .print-hidden {
      display: none !important;
    }

    /* Ensure expanded content is printed */
    .print-visible {
      display: table-row !important;
    }

    /* Force desktop layout */
    @media print {
      .responsive-table-container {
        overflow: visible !important;
      }

      table {
        width: 100% !important;
        min-width: 100% !important;
      }

      body {
        margin: 0 !important;
      }

      /* Reapply visibility settings in print context */
      .print-hidden {
        display: none !important;
      }

      .print-visible {
        display: table-row !important;
      }
    }
  </style>
`;
    document.body.innerHTML = printStyles + printContents.innerHTML;
    window.print();
    setTimeout(() => {
      document.body.innerHTML = originalContents;
      window.location.reload();
    }, 1e3);
  }
