  getnibbidcorrigendum(bidkey) {
    const payload = { bidkeyEncryption: bidkey };
    this.generalService.httpPost(GETNIBBIDCORRIGENDUMSURL.NIBBIDCORRIGENDUMSDATA, payload).subscribe({
      next: (response) => {
        if (response?.msgStatus === "S" && Array.isArray(response.result) && response.result.length > 0) {
          this.corrigendumList = response.result.map((data) => {
            let corrigendumDoc = null;
            let corrigendumDocSize = "";
            try {
              const docObj = JSON.parse(data?.cordocumentString || "{}");
              if (docObj?.id && docObj?.table) {
                corrigendumDoc = {
                  id: docObj.id,
                  table: docObj.table,
                  size: docObj.size || ""
                };
                corrigendumDocSize = docObj.size || "";
              }
            } catch {
              corrigendumDoc = null;
              corrigendumDocSize = "";
            }
            const updatedKeys = (data.fieldUpdate || "").split(",").map((k) => k.trim()).filter((k) => !!k);
            const map4 = {
              bid_type: "bidType",
              bid_sub_type: "bidSubType",
              bid_pattern: "bidPattern",
              bid_title: "bidTitle",
              bid_amount: "bidAmount",
              bid_submission_end_date: "bidSubmissionEndDate",
              bid_open_date: "bidOpenDate",
              first_appeal_hearing_authority: "firstAppealHearingAuthority",
              second_appeal_hearing_authority: "secondAppealHearingAuthority",
              bid_unpublish_date: "bidUnpublishDate"
            };
            const fieldLabels = {
              bid_type: "Bid Type",
              bid_sub_type: "Bid Sub Type",
              bid_pattern: "Bid Pattern",
              bid_title: "Bid Title",
              bid_amount: "Bid Amount",
              bid_submission_end_date: "Bid Submission End Date",
              bid_open_date: "Bid Open Date",
              first_appeal_hearing_authority: "First Appeal Hearing Authority",
              second_appeal_hearing_authority: "Second Appeal Hearing Authority",
              bid_unpublish_date: "Bid Unpublish Date"
            };
            const updatedFields = updatedKeys.map((field) => ({
              field,
              label: fieldLabels[field] || field,
              value: data[map4[field]]
            }));
            return {
              bidCorRemark: data?.bidCorRemark?.trim() || "",
              langName: data?.langName || "",
              bidCorrigendumDate: data?.bidCorrigendumDate ? this.formatDate(data.bidCorrigendumDate) : "",
              corrigendumDoc,
              corrigendumDocSize,
              updatedFields
            };
          });
          this.showCorrigendumTable = this.corrigendumList.length > 0;
        } else {
          this.showCorrigendumTable = false;
          this.corrigendumList = [];
        }
      },
      error: (err) => {
        console.error("API error", err);
        this.showCorrigendumTable = false;
        this.corrigendumList = [];
      }
    });
  }
