  fetchBidDetail() {
    const payload = { rfpKey: this.nibKey };
    this.generalService.httpPost(GETRFPBIDDETAILSURL.GETRFPBIDDETAILSDATA, payload).subscribe({
      next: (response) => {
        if (response && response.msgStatus === "S" && response.result) {
          const result = response.result;
          const { isBidDirectUrl, isPdfAvailable, bidDocParsed } = this.resolveBidPdfType(result.rfpBidDocPdfString);
          this.bidDetails = {
            isPdfAvailable,
            isBidDirectUrl,
            cancelDocPdfSize: bidDocParsed.size,
            document: bidDocParsed,
            rfpBidTitle: result.rfpBidTitle || "",
            bidTypeName: result.bidTypeName || "",
            subTypeName: result.subTypeName || "",
            bidPatternName: result.bidPatternName || "",
            langName: result.langName,
            isEmergencyProcurement: result.isEmergencyProcurement || 0,
            createdDate: this.formatDate(result.createdDate || ""),
            rfpBidPublishDate: this.formatDate(result.rfpBidPublishDate || ""),
            rfpBidSubmissionEndDate: this.formatDate(result.rfpBidSubmissionEndDate || ""),
            rfpBidOpenDate: this.formatDate(result.rfpBidOpenDate || "")
          };
        } else {
          this.bidDetails = null;
          this.showBidDetails = false;
        }
        this.showBidDetails = Object.values(this.bidDetails).some((value) => value !== null && value !== void 0 && value !== "");
      },
      error: (err) => {
        console.error("Error fetching bid details:", err);
        this.showBidDetails = false;
      }
    });
  }
