  applyFilters() {
    const search = this.searchText.trim().toLowerCase();
    const filtered = this.allTenders.filter((tender) => {
      return tender.bidTitle?.toLowerCase().includes(search) || tender.deptName?.toLowerCase().includes(search);
    });
    this.totalPages = this.selectedCount === -1 ? 1 : Math.ceil(filtered.length / this.itemsPerPage);
    if (this.selectedCount === -1) {
      this.displayedTenders = filtered;
    } else {
      const startIndex = (this.currentPage - 1) * this.itemsPerPage;
      const endIndex = startIndex + this.itemsPerPage;
      this.displayedTenders = filtered.slice(startIndex, endIndex);
    }
  }
