  fetchFinancialYears() {
    this.generalService.httpPost(FINANCIALYEARSURL.FINANCIALYEARSDATA, {}).subscribe((response) => {
      if (response && response.msgStatus === "S") {
        this.financialYears = response.result.map((item) => ({
          key: item.key,
          value: item.value
        }));
      }
    });
  }
  fetchDepartments() {
    const payload = {
      actionCheck: "nibsearch",
      finYear: this.financialYear || "2526"
    };
    this.generalService.httpPost(LISTOFDEPTSURL.LISTOFDEPTSDATA, payload).subscribe((response) => {
      if (response && response.msgStatus === "S") {
        this.departments = response.result.map((item) => ({
          deptCode: item.deptCode,
          deptName: item.deptName
        }));
        if (this.financialYear) {
          this.department = "0";
          this.selectedOfficeAddress = "0";
        } else {
          this.department = "";
          this.selectedOfficeAddress = "";
        }
      }
    });
  }
  fetchofficeAddress(deptCode) {
    if (!deptCode || deptCode === "0") {
      this.officeAddresses = [];
      this.showOfficeDropdown = false;
      this.selectedOfficeAddress = "0";
      return;
    }
    const payload = {
      deptCode
    };
    this.generalService.httpPost(DEPTOFFICESURL.DEPTOFFICESDATA, payload).subscribe((response) => {
      if (response && response.msgStatus === "S") {
        this.officeAddresses = response.result.map((item) => ({
          officeAddressId: item.officeAddressId,
          officeName: item.officeName
        }));
        this.showOfficeDropdown = this.officeAddresses.length > 0;
        this.selectedOfficeAddress = "0";
      } else {
        this.officeAddresses = [];
        this.showOfficeDropdown = false;
        this.selectedOfficeAddress = "0";
      }
    }, (error) => {
      console.error("Error fetching office addresses:", error);
      this.officeAddresses = [];
      this.showOfficeDropdown = false;
      this.selectedOfficeAddress = "0";
    });
  }
