  fetchnibDetail(nibcode) {
    const payload = { nibKey: nibcode };
    this.generalService.httpPost(NIBDETAILSURL.NIBDETAILSDATA, payload).subscribe((response) => {
      if (response && response.msgStatus === "S" && response.result) {
        const res = response.result;
        let isDirectUrl = false;
        let nibDocData = null;
        let isPdfAvailable = true;
        if (!res.nibDocPdfString) {
          isPdfAvailable = false;
        } else {
          try {
            nibDocData = JSON.parse(res.nibDocPdfString);
            if (!nibDocData || !nibDocData.size) {
              isPdfAvailable = false;
            }
          } catch (e) {
            nibDocData = this.parseAndDecodeJson(res.nibDocPdfString);
            if (typeof nibDocData === "string") {
              isDirectUrl = true;
            }
            if (!nibDocData || nibDocData === "") {
              isPdfAvailable = false;
            }
          }
        }
        let nibDocPdfSize1 = "";
        if (nibDocData && typeof nibDocData === "object" && nibDocData.size != null) {
          console.log("nib doc data", nibDocData);
          nibDocPdfSize1 = nibDocData.size;
        }
        this.nibDetails = {
          isPdfAvailable,
          nibCode: res.nibCode || "",
          finYear: res.finYear,
          deptCode: res.deptCode || "",
          nibReferenceNo: res.nibReferenceNo || "",
          departmentName: res.deptName || "",
          departmentType: res.departmentType || "",
          procuringEntityName: res.peName || "",
          procuringEntityContact: res.peContact || "",
          financialYear: this.convertYearRange(res.finYear),
          nibPublishDate: res.nibPublishDate || "",
          langName: res.langName || "",
          nibUnpublishDate: res.nibUnpublishDate || "",
          noOfBids: res.noOfBids || "",
          noOfBidsUploaded: res.noOfBidsUploaded || "",
          uploadedOn: res.createdDate || "",
          officeAddressId: res.officeAddressId || "",
          nibDocData,
          nibDocPdf: nibDocPdfSize1,
          isDirectUrl
        };
        this.fetchofficebyId(res.officeAddressId);
        this.fetchpublicPublishDate(res.deptCode + res.finYear + res.nibCode);
        this.fetchgetbidbynib(nibcode);
      }
    });
  }
