    this.appliedEndDateFrom = this.endDateFrom;
    this.appliedEndDateTo = this.endDateTo;
    this.filtersCommitted = !!(this.departmentSearchText || this.titleUbnSearchText || this.locationSearchText || this.selectedBidValue !== "" || this.selectedProcurementType || this.publishDateFrom || this.publishDateTo || this.endDateFrom || this.endDateTo);
